UPDATE quality.tb_data_model_attr SET attr_nm='RCTR_ID', attr_nm_kr='기록관아이디', data_type='VARCHAR', data_len=7, data_decimal_len=0 WHERE dm_id=(SELECT dm_id FROM quality.tb_data_model WHERE dm_nm='RAMP' LIMIT 1) AND obj_nm='tmp_doc_type' AND attr_ord=7;
